    TwistExpander_Vega_Arx::GROW_B_C(PARAMS_GROW);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Vega_Arx::GROW_B_D(PARAMS_GROW);

    //
    // ent: [$water]
    // src: [$vapor]
